-- Insanity Games SaaS — PostgreSQL / Supabase
create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.memberships (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','admin','judge')), primary key(organization_id,user_id));
create table public.events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), slug text not null, name text not null, description text default '', start_at timestamptz, status text not null default 'draft' check(status in ('draft','open','live','finished')), price_cents integer not null default 0 check(price_cents>=0), currency text not null default 'BRL', created_at timestamptz default now(), unique(organization_id,slug), unique(id,organization_id));
create table public.categories (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, name text not null, unique(event_id,name), unique(id,event_id));
create table public.registrations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), category_id uuid not null, athlete_name text not null, email text not null, team text, status text not null default 'pending' check(status in ('pending','paid','cancelled','refunded')), created_at timestamptz default now(), unique(id,event_id), foreign key(category_id,event_id) references public.categories(id,event_id));
create table public.payment_orders (id uuid primary key default gen_random_uuid(), registration_id uuid not null references public.registrations(id), provider text not null, provider_order_id text unique, amount_cents integer not null check(amount_cents>=0), status text not null default 'pending' check(status in ('pending','paid','failed','refunded')), provider_payload jsonb, created_at timestamptz default now());
create table public.workouts (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, name text not null, description text default '', score_type text not null check(score_type in ('time','reps','load','distance')), sort_order integer not null default 0, published boolean not null default false, unique(id,event_id));
create table public.results (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), workout_id uuid not null, registration_id uuid not null, value numeric(14,3) not null check(value>=0), status text not null default 'draft' check(status in ('draft','published','invalid')), entered_by uuid references auth.users(id), updated_at timestamptz default now(), unique(workout_id,registration_id), foreign key(workout_id,event_id) references public.workouts(id,event_id), foreign key(registration_id,event_id) references public.registrations(id,event_id));
create table public.heats (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), workout_id uuid not null, starts_at timestamptz not null, number integer not null check(number>0), unique(id,event_id), foreign key(workout_id,event_id) references public.workouts(id,event_id));
create table public.heat_lanes (heat_id uuid not null references public.heats(id) on delete cascade, registration_id uuid not null references public.registrations(id), lane integer not null check(lane>0), primary key(heat_id,lane), unique(heat_id,registration_id));
create table public.event_points (event_id uuid not null references public.events(id) on delete cascade, place integer not null check(place>0), points integer not null check(points>=0), primary key(event_id,place));
create index on public.events(organization_id); create index on public.registrations(event_id,status); create index on public.results(event_id,status); create index on public.heats(event_id,starts_at);
create or replace function public.can_manage_event(p_event uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.events e join public.memberships m on m.organization_id=e.organization_id where e.id=p_event and m.user_id=auth.uid()) $$;
create or replace function public.can_manage_org(p_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memberships m where m.organization_id=p_org and m.user_id=auth.uid() and m.role in ('owner','admin')) $$;
-- Restrict all tables by default, then grant narrow access policies.
alter table public.organizations enable row level security; alter table public.memberships enable row level security; alter table public.events enable row level security; alter table public.categories enable row level security; alter table public.registrations enable row level security; alter table public.payment_orders enable row level security; alter table public.workouts enable row level security; alter table public.results enable row level security; alter table public.heats enable row level security; alter table public.heat_lanes enable row level security; alter table public.event_points enable row level security;
create policy org_read on public.organizations for select using (true);
create policy membership_read on public.memberships for select using (user_id=auth.uid());
create policy event_read on public.events for select using (status <> 'draft' or public.can_manage_org(organization_id));
create policy event_insert on public.events for insert with check(public.can_manage_org(organization_id));
create policy event_update on public.events for update using(public.can_manage_org(organization_id)) with check(public.can_manage_org(organization_id));
create policy category_read on public.categories for select using(exists(select 1 from public.events e where e.id=event_id and (e.status <> 'draft' or public.can_manage_event(e.id))));
create policy category_write on public.categories for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
create policy workout_read on public.workouts for select using(published or public.can_manage_event(event_id));
create policy workout_write on public.workouts for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
create policy registrations_manage on public.registrations for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
create policy results_read on public.results for select using(status='published' or public.can_manage_event(event_id));
create policy results_write on public.results for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
create policy heats_read on public.heats for select using(exists(select 1 from public.events e where e.id=event_id and (e.status <> 'draft' or public.can_manage_event(event_id))));
create policy heats_write on public.heats for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
create policy heat_lanes_read on public.heat_lanes for select using(exists(select 1 from public.heats h join public.events e on e.id=h.event_id where h.id=heat_id and (e.status <> 'draft' or public.can_manage_event(e.id))));
create policy heat_lanes_write on public.heat_lanes for all using(exists(select 1 from public.heats h where h.id=heat_id and public.can_manage_event(h.event_id))) with check(exists(select 1 from public.heats h where h.id=heat_id and public.can_manage_event(h.event_id)));
create policy points_read on public.event_points for select using(true);
create policy points_write on public.event_points for all using(public.can_manage_event(event_id)) with check(public.can_manage_event(event_id));
-- Registration creation, payment status updates and tenant provisioning must run via trusted server endpoints.
-- Never expose service_role key in a browser; verify payment webhook signatures and idempotency.
